import os
import torch

# ==== File Paths ====
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"
WORKING_DIR = "./working/idea_2"
SUBMISSION_DIR = "./submission"

# Input Files
TRAIN_BSON = os.path.join(INPUT_DIR, "train.bson")
TEST_BSON = os.path.join(INPUT_DIR, "test.bson")
CATEGORY_NAMES = os.path.join(INPUT_DIR, "category_names.csv")
SAMPLE_SUBMISSION = os.path.join(INPUT_DIR, "sample_submission.csv")

# Metadata Files (Generated by previous steps)
TRAIN_META_CSV = os.path.join(METADATA_DIR, "train.csv")
VAL_META_CSV = os.path.join(METADATA_DIR, "val.csv")
TEST_META_CSV = os.path.join(METADATA_DIR, "test.csv")

# Output Paths
CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
LOG_DIR = os.path.join(WORKING_DIR, "logs")
SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

# ==== Data Configuration ====
NUM_CLASSES = 5270
IMG_SIZE = 224  # Resizing 180x180 native to 224x224 for standard ResNet
CHANNELS = 3

# ImageNet Normalization Statistics
MEAN = [0.485, 0.456, 0.406]
STD = [0.229, 0.224, 0.225]

# BSON Constants
BSON_IMG_KEY = "imgs"
BSON_PICTURE_KEY = "picture"

# ==== Model Configuration ====
MODEL_ARCH = "resnet50"
PRETRAINED = True
DROPOUT = 0.0  # ResNet usually doesn't use dropout in the backbone, maybe in head

# ==== Training Configuration ====
SEED = 42
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
NUM_WORKERS = 12  # Maximize vCPU usage
PIN_MEMORY = True

# Hyperparameters
BATCH_SIZE = 256  # A100 40GB can handle large batches
EPOCHS = 2  # Training on full 12M images, 2 epochs is sufficient with OneCycle
LEARNING_RATE = 0.01  # Max LR for OneCycle
WEIGHT_DECAY = 1e-4
MOMENTUM = 0.9

# Regularization
LABEL_SMOOTHING = 0.1
MIXUP_ALPHA = 0.2
USE_MIXUP = True

# Debugging / Development
DEBUG = False  # Set to True to run on a small subset
DEBUG_SAMPLE_SIZE = 50000


# ==== Utility Functions ====
def setup_directories():
    """
    Creates necessary directories for checkpoints and submissions.
    """
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(CHECKPOINT_DIR, exist_ok=True)
    os.makedirs(LOG_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    print(f"Directories initialized at {WORKING_DIR} and {SUBMISSION_DIR}")


# Initialize directories on import
setup_directories()
